<?php declare(strict_types=1);
use Kulturhus\Verein\Settings\{MailInput,GeneralRequests};
use Kulturhus\Verein\MailChannelSettings;
$mt=static fn(string $text):string=>\Kulturhus\Native\Language\MailSettingsMessages::text($text,$mailsettingsMessages);
$mv=static fn(mixed $value):string=>is_bool($value)?($value?'1':'0'):(is_scalar($value)?(string)$value:'');
$murl=static fn(array $query=[]):string=>url(['view'=>'settings','section'=>'mail','mailsettings_scope'=>$mailsettingsScope]+$query);
$marea=static fn(string $scope):string=>$scope==='mail_channels'?'Postfächer & Versandzuordnungen':'Rechnungspostfach';
$mlabels=['override'=>'Für den Versand verwenden','host'=>'SMTP-Server','port'=>'SMTP-TLS-Port','user'=>'SMTP-Benutzername','from'=>'Absenderadresse','name'=>'Angezeigter Absendername','reply'=>'Antwortadresse','enabled'=>'IMAP-Eingang aktivieren','smtp_enabled'=>'Rechnungsversand aktivieren','email'=>'Rechnungsadresse','imap_host'=>'IMAP-Server','imap_user'=>'IMAP-Benutzername','folder'=>'IMAP-Ordner','since'=>'Abrufbeginn (JJJJ-MM-TT)','smtp_host'=>'SMTP-Server','smtp_port'=>'SMTP-TLS-Port','smtp_user'=>'SMTP-Benutzername','smtp_name'=>'Angezeigter Absendername'];
$mvalues=static function(array $data,?array $passwords=[],?string $scope=null,?string $senderName=null)use($mt,$mv,$mlabels,$mailsettingsScope):void{
 $scope??=$mailsettingsScope;?><dl class="general-settings-description"><?php
 if($scope==='mail_channels'){
  foreach($data['channels']as $channel=>$row){?><dt><?= e($mt(MailChannelSettings::CHANNELS[$channel])) ?></dt><dd><dl><?php foreach($mlabels as $field=>$label)if(array_key_exists($field,$row)){?><dt><?= e($mt($label)) ?></dt><dd><?= e(is_bool($row[$field])?$mt($row[$field]?'Ja':'Nein'):$mv($row[$field])) ?></dd><?php } if($passwords!==null){?><dt><?= e($mt('Gespeichertes Passwort')) ?></dt><dd><?= e($mt(!empty($passwords[$channel])?'Vorhanden':'Nicht hinterlegt')) ?></dd><?php } ?></dl></dd><?php }
  foreach($data['routes']as $purpose=>$channel){?><dt><?= e($mt(MailChannelSettings::PURPOSES[$purpose])) ?></dt><dd><?= e($mt(MailChannelSettings::CHANNELS[$channel]??$channel)) ?></dd><?php }
 }else foreach($mlabels as $field=>$label)if(array_key_exists($field,$data)){?><dt><?= e($mt($label)) ?></dt><dd><?= e(is_bool($data[$field])?$mt($data[$field]?'Ja':'Nein'):$mv($data[$field])) ?></dd><?php }
 if($scope==='invoice_mailbox'&&$senderName!==null){?><dt><?= e($mt('Wirksamer Absendername')) ?></dt><dd><?= e($senderName) ?></dd><?php }
 if($scope==='invoice_mailbox'&&$passwords!==null)foreach(['imap_password'=>'IMAP-Passwort','smtp_password'=>'SMTP-Passwort']as $field=>$label){?><dt><?= e($mt($label)) ?></dt><dd><?= e($mt(!empty($passwords[$field])?'Vorhanden':'Nicht hinterlegt')) ?></dd><?php } ?></dl><?php
};
$mintents=static function(array $input)use($mt):void{?><ul><?php foreach($input['credential_intents']as $path=>$intent): ?><li><?= e($mt(str_contains($path,'.')?MailChannelSettings::CHANNELS[explode('.',$path)[1]].' · SMTP-Passwort':($path==='imap_password'?'IMAP-Passwort':'SMTP-Passwort'))) ?>: <?= e($mt($intent['replacement']?'Neues Passwort für diesen Entwurf vorgemerkt.':(in_array($intent['clear'],[true,1,'1'],true)?'Gespeichertes Passwort wird ausdrücklich entfernt.':'Gespeichertes Passwort bleibt erhalten.'))) ?></li><?php endforeach ?></ul><?php };
?>
<link rel="stylesheet" href="general-settings-native.css?v=1">
<div class="general-settings-native" data-mailsettings-native>
<section class="card"><h2><?= e($mt('Postfächer & Versand')) ?></h2><p><?= e($mt('Lege fest, über welche Postfächer der Verein Nachrichten sendet und Rechnungen empfängt.')) ?></p><p><?= e($mt('Speichern bestätigt die Einstellungen. Eine Verbindung wird dabei nicht getestet und keine Nachricht versendet oder abgerufen.')) ?></p><p><a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'finance','tab'=>'inbox'])) ?>"><?= e($mt('Eingegangene Rechnungen ansehen')) ?></a> <a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'settings','tab'=>'system'])) ?>"><?= e($mt('Verbindungen & Systemstatus')) ?></a></p></section>
<?php if(!$mailsettingsState): ?><section class="card"><p><?= e($mt('Postfacheinstellungen sind für diesen Zugriff nicht verfügbar.')) ?></p></section></div><?php return;endif ?>
<?php foreach($mailsettingsState['errors']as $piece=>$problem): ?><section class="card" data-mailsettings-error="<?= e($piece) ?>"><p role="alert"><?= e($mt($problem)) ?></p></section><?php endforeach ?>
<?php if($mailsettingsState['receipt']):$receipt=$mailsettingsState['receipt']; ?><section class="card" data-mailsettings-receipt="<?= e($receipt['key']) ?>"><h2><?= e($mt('Postfachbestätigung')) ?></h2><p><code><?= e($receipt['key']) ?></code> · <?= e($mt('Fassung')) ?> <?= e($receipt['result']['version']) ?> · <?= e($receipt['created_at']) ?></p><p><?= e($mt('Diese Bestätigung erhält die damaligen Angaben und Passwortaktionen ohne Passwortinhalt. Spätere Änderungen ersetzen sie nicht.')) ?></p><p><a class="btn btn-outline theme-secondary" data-navigation-native data-mailsettings-download download href="<?= e($murl(['mailsettings_original'=>$receipt['key']])) ?>"><?= e($mt('Genau diese Bestätigung herunterladen')) ?></a> <a class="btn btn-outline theme-secondary" href="<?= e($murl(['mailsettings_new'=>'1'])) ?>"><?= e($mt('Neuen eigenen Postfachentwurf öffnen')) ?></a></p><?php $mvalues($receipt['result']['data'],$receipt['result']['passwords'],null,$receipt['result']['sender_name']??null); ?><details class="general-settings-values" data-mailsettings-original-input><summary><?= e($mt('Damals vollständige gewünschte Angaben')) ?></summary><?php $mvalues($receipt['input']['data'],$receipt['review']['current']['passwords'],null,$receipt['review']['normalized']['sender_name']??null);$mintents($receipt['input']); ?></details></section><?php endif ?>
<?php foreach(MailInput::SCOPES as $area):$current=$mailsettingsState['current'][$area]??null; ?><details class="card" data-mailsettings-current="<?= e($area) ?>"><summary><?= e($mt($marea($area))) ?> · <?= e($mt('Aktuell gespeichert')) ?><?= $current?' · '.e($mt('Fassung')).' '.e($current['version']):'' ?></summary><?php if($current):$mvalues($current['data'],$current['passwords'],$area,$current['sender_name']??null);else: ?><p><?= e($mt('Dieses Postfach konnte nicht geladen werden.')) ?></p><?php endif ?></details><?php endforeach ?>
<?php if(!$mailsettingsDraft||$mailsettingsDraft['accepted']!==null): ?><section class="card"><h2><?= e($mt('Postfacheinstellungen bearbeiten')) ?></h2><?php foreach(MailInput::SCOPES as $area): ?><a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'settings','section'=>'mail','mailsettings_scope'=>$area,'mailsettings_new'=>'1'])) ?>"><?= e($mt($marea($area))) ?></a><?php endforeach ?></section><?php endif ?>
<?php if($mailsettingsDraft&&$mailsettingsDraft['accepted']===null):$draft=$mailsettingsDraft;$input=$draft['input'];$editable=!$draft['pending']&&!isset($mailsettingsState['errors']['key']);$data=$input['data'];
$mfield=static function(string $path,string $label,string $type='text',array $options=[])use($data,$mt,$mv):void{
 $value=$mv(MailInput::value($data,$path));$name='data['.str_replace('.','][',$path).']';$id='mail-'.str_replace('.','-',$path); ?><label class="setting-field" for="<?= e($id) ?>"><?= e($mt($label)) ?><?php if($type==='select'): ?><select class="form-control" id="<?= e($id) ?>" name="<?= e($name) ?>" data-mailsettings-field="<?= e($path) ?>"><?php if(!array_key_exists($value,$options)): ?><option value="<?= e($value) ?>" selected><?= e($value) ?></option><?php endif ?><?php foreach($options as $v=>$text): ?><option value="<?= e($v) ?>" <?= $value===(string)$v?'selected':'' ?>><?= e($mt($text)) ?></option><?php endforeach ?></select><?php else: ?><input class="form-control" type="text" id="<?= e($id) ?>" name="<?= e($name) ?>" value="<?= e($value) ?>" data-mailsettings-field="<?= e($path) ?>"><?php endif ?></label><?php
};
$mpassword=static function(string $path,string $label)use($input,$mfield,$mt):void{
 $clear=str_contains($path,'.')?substr($path,0,strrpos($path,'.')+1).'clear_password':'clear_'.$path;$name='data['.str_replace('.','][',$path).']'; ?><div class="setting-field"><label><?= e($mt($label)) ?><input class="form-control" type="password" name="<?= e($name) ?>" value="" autocomplete="new-password" data-mailsettings-password="<?= e($path) ?>"></label><p><?= e($mt(!empty($input['credential_intents'][$path]['replacement'])?'Neues Passwort für diesen Entwurf vorgemerkt.':'Leer lassen, um das gespeicherte Passwort beizubehalten.')) ?></p><?php if(!empty($input['credential_intents'][$path]['replacement'])): ?><button class="btn btn-outline theme-secondary" name="mailsettings_intent" value="forget:<?= e($path) ?>"><?= e($mt('Vorgemerktes neues Passwort vergessen')) ?></button><?php endif ?><?php $mfield($clear,'Gespeichertes Passwort ausdrücklich entfernen','select',['0'=>'Nein','1'=>'Ja']); ?></div><?php
};
?><section class="card" data-mailsettings-editor="<?= e($draft['id']) ?>"><h2><?= e($mt($marea($mailsettingsScope))) ?></h2><p><?= e($mt('Ungespeicherter eigener Entwurf')) ?> · <?= e($mt('Fassung')) ?> <?= e($input['version']) ?> · <code><?= e($draft['key']) ?></code></p>
<?php if($draft['pending']): ?><p role="status"><?= e($mt('Postfachausgang nicht bestätigt. Die ursprüngliche Bestätigung über ihre Kennung lesen.')) ?></p><a class="btn btn-outline theme-secondary" href="<?= e($murl(['mailsettings_draft'=>$draft['id'],'mailsettings_receipt'=>$draft['key']])) ?>"><?= e($mt('Ursprünglichen Postfachausgang lesend prüfen')) ?></a><?php endif ?>
<?php if(isset($mailsettingsState['errors']['key'])): ?><section data-mailsettings-readonly-draft><p><?= e($mt('Zum Ändern muss der ursprüngliche private Serverschlüssel wieder verfügbar sein. Der vollständige Entwurf bleibt erhalten.')) ?></p><?php $mvalues($input['data'],null);$mintents($input); ?></section><?php endif ?>
<form method="post" action="<?= e($murl()) ?>" novalidate data-mailsettings-form><?= csrf().hidden('action','mail-settings-native').hidden('mailsettings_draft',$draft['id']) ?>
<?php if($editable): ?>
<?php if($mailsettingsScope==='mail_channels'):foreach(MailChannelSettings::defaults()['channels']as $channel=>$defaults): ?><fieldset class="general-settings-row"><legend><?= e($mt(MailChannelSettings::CHANNELS[$channel])) ?></legend><div class="form-grid"><?php foreach($defaults as $field=>$default){$path='channels.'.$channel.'.'.$field;$mfield($path,$mlabels[$field],in_array($field,['override','port'],true)?'select':'text',$field==='override'?['0'=>'Nein','1'=>'Ja']:($field==='port'?['465'=>'465 · TLS','587'=>'587 · STARTTLS']:[]));}$mpassword('channels.'.$channel.'.password','SMTP-Passwort'); ?></div></fieldset><?php endforeach ?><fieldset class="general-settings-row"><legend><?= e($mt('Versandzwecke zuordnen')) ?></legend><div class="form-grid"><?php foreach(MailChannelSettings::PURPOSES as $purpose=>$label)$mfield('routes.'.$purpose,$label,'select',MailChannelSettings::CHANNELS); ?></div></fieldset>
<?php else: ?><p><?= e($mt('IMAP-Eingang und SMTP-Versand sind unabhängig aktivierbar. IMAP verwendet TLS auf Port 993. Ein leerer Absendername verwendet den eigenen Vereinsnamen.')) ?></p><div class="form-grid"><?php foreach(\Kulturhus\Verein\InvoiceMailbox::defaults()as $field=>$default)$mfield($field,$mlabels[$field],is_bool($default)||$field==='smtp_port'?'select':'text',is_bool($default)?['0'=>'Nein','1'=>'Ja']:($field==='smtp_port'?['465'=>'465 · TLS','587'=>'587 · STARTTLS']:[]));$mpassword('imap_password','IMAP-Passwort');$mpassword('smtp_password','SMTP-Passwort'); ?></div><?php endif ?>
<div class="settings-actions"><button class="btn btn-solid theme-primary" name="mailsettings_intent" value="preview"><?= e($mt('Vollständige Postfacheinstellungen prüfen')) ?></button><?php foreach(MailInput::SCOPES as $area)if($area!==$mailsettingsScope): ?><button class="btn btn-outline theme-secondary" name="mailsettings_intent" value="switch:<?= e($area) ?>"><?= e($mt('Entwurf erhalten und anderen Bereich öffnen')) ?></button><?php endif ?></div>
<?php endif ?>
<div class="settings-actions"><?php if(isset($mailsettingsState['errors']['key'])): ?><a class="btn btn-outline theme-secondary" href="<?= e($murl(['mailsettings_draft'=>$draft['id']])) ?>"><?= e($mt('Gespeicherten Entwurf erneut öffnen')) ?></a><?php else: ?><button class="btn btn-outline theme-secondary" name="mailsettings_intent" value="current"><?= e($mt('Aktuellen Stand bewusst erneut prüfen')) ?></button><?php endif ?><button class="btn btn-outline theme-secondary" name="mailsettings_intent" value="discard"><?= e($mt('Eigenen ungespeicherten Entwurf verwerfen')) ?></button></div></form>
<?php if($editable&&$draft['review']):$review=$draft['review']; ?><section data-mailsettings-review><h3><?= e($mt('Vollständige Postfachprüfung')) ?></h3><?php $mvalues($review['normalized']['data'],$review['normalized']['passwords'],null,$review['normalized']['sender_name']??null); ?><details><summary><?= e($mt('Vollständige gewünschte Angaben')) ?></summary><?php $mvalues($input['data'],$review['current']['passwords'],null,$review['normalized']['sender_name']??null); ?><?php $mintents($input); ?></details><form method="post" action="<?= e($murl()) ?>" data-mailsettings-accept><?= csrf().hidden('action','mail-settings-native').hidden('mailsettings_draft',$draft['id']).hidden('mailsettings_key',$draft['key']).hidden('mailsettings_review',$review['hash']) ?><label class="general-settings-check"><input class="check" type="checkbox" name="mailsettings_approved" value="1"> <span><?= e($mt('Die vollständigen Postfacheinstellungen und Passwortaktionen sind geprüft.')) ?></span></label><button class="btn btn-solid theme-primary" name="mailsettings_intent" value="accept"><?= e($mt('Geprüfte Postfacheinstellungen bestätigen')) ?></button></form></section><?php endif ?></section><?php endif ?>
<?php if($mailsettingsDraftIndex): ?><section class="card"><h2><?= e($mt('Entwürfe')) ?></h2><ul><?php foreach($mailsettingsDraftIndex as $stored): ?><li><a href="<?= e(url(['view'=>'settings','section'=>'mail','mailsettings_scope'=>$stored['section'],'mailsettings_draft'=>$stored['id']])) ?>"><?= e($mt($marea($stored['section']))) ?> · <?= e($stored['key']) ?></a></li><?php endforeach ?></ul></section><?php endif ?>
<section class="card"><h2><?= e($mt('Postfachbestätigungen')) ?></h2><form method="get"><?= hidden('view','settings').hidden('section','mail').hidden('mailsettings_scope',$mailsettingsScope) ?><div class="form-grid"><label><?= e($mt('Bestätigungen suchen')) ?><input class="form-control" name="mailsettings_history_q" placeholder="<?= e($mt('Kennung, Fassung oder Zeitpunkt')) ?>" value="<?= e(is_string($_GET['mailsettings_history_q']??null)?$_GET['mailsettings_history_q']:'') ?>"></label><label><?= e($mt('Seite')) ?><input class="form-control" name="mailsettings_history_page" value="<?= e(is_scalar($_GET['mailsettings_history_page']??'1')?(string)($_GET['mailsettings_history_page']??'1'):'') ?>"></label></div><button class="btn btn-outline theme-secondary"><?= e($mt('Suchen')) ?></button></form><?php if($mailsettingsState['history']):$history=$mailsettingsState['history']; ?><p><?= e($history['total']) ?> · <?= e($mt('Seiten')) ?> <?= e($history['pages']) ?></p><ul><?php foreach($history['rows']as $row): ?><li><a href="<?= e($murl(['mailsettings_receipt'=>$row['request_key']])) ?>"><?= e($mt('Fassung')) ?> <?= e($row['version']) ?> · <?= e($row['created_at']) ?> · <?= e($row['request_key']) ?></a></li><?php endforeach ?></ul><?php endif ?></section>
